//! Retained hash-bound 0.109.0 native raid action graph. Current Mark payloads
//! and Highlord's damage correction are bound by mograine-marks-0.127.0.md.
//! Native payloads are not the semantic ABI.
use super::RawBossAbility;
#[derive(Clone, Copy, Debug)]
pub struct NativeAction { pub native_tag: u8, pub words: [u32;12], pub children: &'static [usize], pub repeat: f32, pub duration: f32, pub ability: RawBossAbility }

impl NativeAction {
    /// Current native duration helper: a Mark reserves its escape window,
    /// and a sequence includes the duration of its final child. Other tags
    /// retain the recovered annotations instead of changing their contracts.
    pub fn blocking_duration(&self) -> f32 {
        match self.native_tag {
            11 => f32::from_bits(self.words[4])
                .max(f32::from_bits(self.words[2]) / 7.0 + 0.5),
            18 => self.children.last().map_or(0.0, |last| {
                ACTIONS[*last].blocking_duration()
                    + (self.children.len() - 1) as f32 * f32::from_bits(self.words[4])
            }),
            _ => self.duration,
        }
    }
}

pub fn native_action(index: usize) -> RawBossAbility { ACTIONS[index].ability }
